/* From Uiverse.io by SanthoshSJ-Dev - Tags: simple, material design, input, animated, line, text */
.__UIV_SCOPE__ .input-wrapper {
  position: relative;
  width: 200px;
  margin: 50px auto;
}

.__UIV_SCOPE__ .input-box {
  font-size: 16px;
  padding: 10px 0;
  border: none;
  border-bottom: 2px solid #ccc;
  color: #08AEEA;
  width: 100%;
  background-color: transparent;
  transition: border-color 0.3s ease-in-out;
}

.__UIV_SCOPE__ .underline {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background-color: #08AEEA;
  transform: scaleX(0);
  transition: transform 0.3s ease-in-out;
}

.__UIV_SCOPE__ .input-box:focus {
  border-color: #08AEEA;
  outline: none;
}

.__UIV_SCOPE__ .input-box:focus + .underline {
  transform: scaleX(1);
}
